let meals={jeudi:{petitdej:false,dej:false,diner:false},vendredi:{petitdej:false,dej:false,diner:false},samedi:{petitdej:false,dej:false,diner:false}};function loadPilot(){const d=document.getElementById('pilot-meals');if(!d)return;d.innerHTML=Object.keys(meals).map(j=>`<div><h3>${j}</h3><label><input type='checkbox' onchange="toggleMeal('${j}','petitdej')"> Petit-déjeuner</label><br><label><input type='checkbox' onchange="toggleMeal('${j}','dej')"> Déjeuner</label><br><label><input type='checkbox' onchange="toggleMeal('${j}','diner')"> Dîner</label></div>`).join('');} function toggleMeal(j,r){meals[j][r]=!meals[j][r];} function simulatePayment(){alert('Paiement simulé : OK');} function loadStaff(){const d=document.getElementById('staff-list');if(!d)return;d.innerHTML='<p>Aucune donnée (prototype vide)</p>';} function loadAdmin(){const d=document.getElementById('admin-stats');if(!d)return;d.innerHTML='<p>Prévisions indisponibles (prototype vide)</p>';} window.onload=function(){loadPilot();loadStaff();loadAdmin();};